import React from 'react';
import {act, render, cleanup} from '@testing-library/react';
import {ThemeProvider} from '@gravity-ui/uikit';
import {afterEach, expect, it, vi} from 'vitest';
import {CpuLoadChart, type CpuLoadChartHandle} from './CpuLoadChart';
import {SimulatedCpuLoadSource} from './cpuLoadSource';

afterEach(() => { cleanup(); console.log('after cleanup tooltips:', document.querySelectorAll('.yagr-tooltip').length); });

it('mount only', () => {
  const source = new SimulatedCpuLoadSource({intervalMs: 1000, windowMs: 60_000, now: () => 1_000_000});
  const h = React.createRef<CpuLoadChartHandle>();
  render(<ThemeProvider theme="light"><CpuLoadChart ref={h} source={source} windowMs={60_000} /></ThemeProvider>);
  console.log('mounted tooltips:', document.querySelectorAll('.yagr-tooltip').length, 'chart id', h.current!.getChart()!.id);
});
it('theme switch', () => {
  const source = new SimulatedCpuLoadSource({intervalMs: 1000, windowMs: 60_000, now: () => 1_000_000});
  const h = React.createRef<CpuLoadChartHandle>();
  const r = render(<ThemeProvider theme="light"><CpuLoadChart ref={h} source={source} windowMs={60_000} /></ThemeProvider>);
  console.log('before switch:', document.querySelectorAll('.yagr-tooltip').length);
  r.rerender(<ThemeProvider theme="dark"><CpuLoadChart ref={h} source={source} windowMs={60_000} /></ThemeProvider>);
  console.log('after switch:', document.querySelectorAll('.yagr-tooltip').length);
});
it('rebuild', async () => {
  let now = 1_000_000;
  const source = new SimulatedCpuLoadSource({intervalMs: 1000, windowMs: 60_000, now: () => now});
  const h = React.createRef<CpuLoadChartHandle>();
  render(<ThemeProvider theme="light"><CpuLoadChart ref={h} source={source} windowMs={60_000} /></ThemeProvider>);
  act(() => { now += 30_000; source.tick(); });
  await act(async () => { await new Promise((r) => requestAnimationFrame(() => r(undefined))); });
  console.log('after rebuild:', document.querySelectorAll('.yagr-tooltip').length);
});
EOF
