import React from 'react';
import {act, render} from '@testing-library/react';
import {ThemeProvider} from '@gravity-ui/uikit';
import {expect, it, vi} from 'vitest';
import {CpuLoadChart, type CpuLoadChartHandle} from './CpuLoadChart';
import {SimulatedCpuLoadSource} from './cpuLoadSource';

function mk() {
  let now = 1_000_000;
  const source = new SimulatedCpuLoadSource({intervalMs: 1000, windowMs: 60_000, now: () => now});
  return {source, advance: (ms: number) => { now += ms; source.tick(); }};
}
const count = () => document.querySelectorAll('.yagr-tooltip').length;

it('A: advance then unmount, no spies', () => {
  const {source, advance} = mk();
  const r = render(<ThemeProvider theme="light"><CpuLoadChart source={source} windowMs={60_000} /></ThemeProvider>);
  act(() => advance(1000));
  r.unmount();
  console.log('A after unmount:', count());
  document.querySelectorAll('.yagr-tooltip').forEach((e) => e.remove());
});
it('B: raf spies only', () => {
  const {source} = mk();
  const rafSpy = vi.spyOn(window, 'requestAnimationFrame');
  const cafSpy = vi.spyOn(window, 'cancelAnimationFrame');
  const r = render(<ThemeProvider theme="light"><CpuLoadChart source={source} windowMs={60_000} /></ThemeProvider>);
  r.unmount();
  console.log('B after unmount:', count());
  vi.restoreAllMocks();
  document.querySelectorAll('.yagr-tooltip').forEach((e) => e.remove());
});
it('C: subscribe mock only', () => {
  const {source} = mk();
  vi.spyOn(source, 'subscribe').mockImplementation((l) => SimulatedCpuLoadSource.prototype.subscribe.call(source, l));
  const r = render(<ThemeProvider theme="light"><CpuLoadChart source={source} windowMs={60_000} /></ThemeProvider>);
  r.unmount();
  console.log('C after unmount:', count());
  vi.restoreAllMocks();
});
it('D: unmount, then tick (listener still attached?)', () => {
  const {source, advance} = mk();
  const r = render(<ThemeProvider theme="light"><CpuLoadChart source={source} windowMs={60_000} /></ThemeProvider>);
  r.unmount();
  console.log('D after unmount:', count());
  act(() => advance(1000));
  console.log('D after tick:', count());
});
EOF
